create table stock_in_order
(
    order_id       bigint auto_increment comment '主键'
        primary key,
    order_no       varchar(64)      null comment '单据号',
    order_type     varchar(32)      null comment '单据类型',
    order_status   varchar(32)      null comment '单据状态',
    check_status   varchar(32)      null comment '检验状态',
    check_by       varchar(64)      null comment '检验员',
    del_flag       char default '0' null comment '删除标识',
    create_by      varchar(64)      null comment '创建人',
    create_time    datetime         null comment '创建时间',
    update_by      varchar(64)      null comment '修改人',
    update_time    datetime         null comment '修改时间',
    allot_no       varchar(32)      null comment '关联调拨单号',
    warehouse_code varchar(64)      null comment '仓库编码',
    warehouse_name varchar(64)      null comment '仓库名称',
    prod_order_no  varchar(64)      null comment '关联生产工单号（完工入库时使用）'
)
    comment '入库单' collate = utf8mb4_general_ci
                     row_format = DYNAMIC;

create index idx_in_order_allot_no
    on stock_in_order (allot_no);

